// Phase 1: detect cycle. Phase 2: find cycle entry point.
function detectCycleStart(head) {
  if (!head || !head.next) return null;

  let slow = head;
  let fast = head;

  // phase 1 - detect if cycle exists
  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) break; // met inside cycle
  }

  // no cycle - fast reached end
  if (fast === null || fast.next === null) return null;

  // phase 2 - find cycle entry point
  // reset one pointer to head, move both at speed 1
  slow = head;
  while (slow !== fast) {
    slow = slow.next;
    fast = fast.next;
  }

  return slow; // cycle start node
}

// Find middle of linked list
function findMiddle(head) {
  let slow = head;
  let fast = head;
  // stop when fast can't take two steps
  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
  }
  return slow; // second middle for even-length lists
}
